head.script:
scwin.onpageload = function() {
scwin.tabIndex = 1;
};
scwin.onpageunload = function() {};
scwin.addTab = function(label, tabId, src) {
    var tabOpt = {
        label: label,
        closable: true
    };
    var contOpt = {
        frameMode: "wframe",
        scope: true,
        src: src,
        alwaysDraw: false,
        title: tabId
    };
    tac_main.addTab(tabId, tabOpt, contOpt);
};
scwin.btn_trigger1_onclick = function(e) {
    var tabId = "tab" + scwin.tabIndex;
    var label = tabId;
    var src = "dataList_removeAll_WEFF-674_(WSQ-4016)_sub" + ".xml";
    scwin.addTab(label, tabId, src);
    scwin.tabIndex++;
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id + 'tac_main_contents_tab1_body_gridView1_body_tbody').children[0]).hasClass('w2grid_hidedRow') == true;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tac_main_contents_tab1_body_trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tac_main_contents_tab1_body_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
